    "credit": "Trust \"Tru\" Katsande",
    "license": "Unsplash",
    "link": "https://unsplash.com/photos/woman-looking-on-microscope-inside-room-6q5QG8iIgRo?utm_source=dia_news&utm_medium=referral",
